def build():
    for rel, pairs in PAGES.items():
        src = os.path.join(DOCS, rel)
        s = open(src, encoding="utf-8").read()
        missing = []
        for a, b in COMMON + pairs:
            if a in s:
                s = s.replace(a, b)
            elif (a, b) in pairs:
                missing.append(a[:60])
        depth = rel.count("/")
        up = "../" * depth
        # canonical + hreflang + asset paths
        en_url = f"{SITE}/{rel.replace('index.html', '')}"
        es_url = f"{SITE}/es/{rel.replace('index.html', '')}"
        s = s.replace(f'<link rel="canonical" href="{en_url}">', f'<link rel="canonical" href="{es_url}"><link rel="alternate" hreflang="en" href="{en_url}"><link rel="alternate" hreflang="es" href="{es_url}"><link rel="alternate" hreflang="x-default" href="{en_url}">')
        s = s.replace(f'<meta property="og:url" content="{en_url}">', f'<meta property="og:url" content="{es_url}">')
        s = s.replace(f'href="{up}style.css"', f'href="{up}../style.css"').replace(f'src="{up}config.js"', f'src="{up}../config.js"').replace(f'src="{up}app.js"', f'src="{up}../app.js"')
        s = s.replace('<body data-drop=', '<body data-lang="es" data-drop=')
        dst = os.path.join(DOCS, "es", rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        open(dst, "w", encoding="utf-8", newline="\n").write(s)
        print("es/" + rel, "missing:" if missing else "ok", *missing)
    # English pages get the hreflang alternates too
    for rel in PAGES:
        src = os.path.join(DOCS, rel)
        s = open(src, encoding="utf-8").read()
        en_url = f"{SITE}/{rel.replace('index.html', '')}"
        es_url = f"{SITE}/es/{rel.replace('index.html', '')}"
        tag = f'<link rel="alternate" hreflang="es" href="{es_url}">'
        if tag not in s:
            s = s.replace(f'<link rel="canonical" href="{en_url}">', f'<link rel="canonical" href="{en_url}"><link rel="alternate" hreflang="en" href="{en_url}">{tag}<link rel="alternate" hreflang="x-default" href="{en_url}">')
            open(src, "w", encoding="utf-8", newline="\n").write(s)


if __name__ == "__main__":
    build()
